package org.apache.druid.query.filter;

import com.fasterxml.jackson.databind.InjectableValues;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.apache.druid.jackson.DefaultObjectMapper;
import org.apache.druid.js.JavaScriptConfig;
import org.junit.Assert;
import org.junit.Test;

import java.io.IOException;

public class JavaScriptDimFilterExploitTest
{
  @Test
  public void testExploit() throws IOException
  {
    ObjectMapper mapper = new DefaultObjectMapper();
    mapper.setInjectableValues(new InjectableValues.Std().addValue(JavaScriptConfig.class, new JavaScriptConfig(false)));

    String json = "{\n" +
                  "  \"type\": \"javascript\",\n" +
                  "  \"function\": \"function(){ return true; }\",\n" +
                  "  \"dimension\": \"dim\",\n" +
                  "  \"\": {\n" +
                  "    \"enabled\": true\n" +
                  "  }\n" +
                  "}";

    try {
      JavaScriptDimFilter filter = mapper.readValue(json, JavaScriptDimFilter.class);
      filter.toFilter(); 
      Assert.fail("Should have thrown exception because JavaScript is disabled");
    } catch (IllegalStateException e) {
      Assert.assertEquals("JavaScript is disabled", e.getMessage());
    } catch (Exception e) {
       // if it throws other exception (like UnrecognizedPropertyException), that's also interesting
       System.out.println("Exception: " + e);
       if (e.getMessage().contains("JavaScript is disabled")) {
           // Good
       } else {
           throw e;
       }
    }
  }
}

